      "id": "rcds-matlab",
      "group": "RCDS",
      "title": "MATLAB",
      "gist": "Run MATLAB and its toolboxes on RCDS standalone servers or as a cluster job via module load.",
      "source": "https://hpc.uidaho.edu/compute/Applications/MATLAB.html",
